import sympy as sp

def calculate_A(a_list):
    n = len(a_list)
    A = 0
    for x in range(n):
        term = 1
        for y in range(n):
            if x != y:
                term *= (a_list[x] * a_list[y] - 1) / (a_list[x] - a_list[y])
        A += term
    return A

a_vals = [sp.Symbol('a1'), sp.Symbol('a2'), sp.Symbol('a3'), sp.Symbol('a4'), sp.Symbol('a5')]
for n in range(2, 7):
    current_a = a_vals[:n]
    res = calculate_A(current_a)
    print(f"n={n}, A_{n-1} = {sp.simplify(res)}")

